using System.Security.Claims;
using System.Text.Json;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Sem.Authentication;
using Sem.Web.Data;
using Sem.Web.Runtime;
int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;}
var file=Path.Combine(Path.GetTempPath(),"sem-overview-"+Guid.NewGuid().ToString("N")+".db");
try{
 var services=new ServiceCollection();services.AddLogging();services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlite("Data Source="+file));services.AddIdentityCore<ApplicationUser>(o=>o.Stores.SchemaVersion=IdentitySchemaVersions.Version3).AddEntityFrameworkStores<ApplicationDbContext>();await using var provider=services.BuildServiceProvider();await using var scope=provider.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();var users=scope.ServiceProvider.GetRequiredService<UserManager<ApplicationUser>>();await SqliteStorageInitializer.InitializeAsync(db);
 var actor=new ApplicationUser{Id="actor",UserName="actor@example.invalid",Email="actor@example.invalid",EmailConfirmed=true,Enabled=true,DisplayName="合成管理者",SecurityStamp="stamp"};db.Users.Add(actor);db.Users.Add(new(){Id="other",DisplayName="<img src=x> 他人",UserName="other@example.invalid",Email="PRIVATE_EMAIL"});await db.SaveChangesAsync();Check((await users.AddOrUpdatePasskeyAsync(actor,new([1],[11,22],DateTimeOffset.UtcNow,777,["internal"],true,true,true,[44],[55]))).Succeeded,"合成パスキー");
 var identity=new IdentityOptions();ClaimsPrincipal Who(string stamp="stamp",bool duplicate=false,string? session="session")=>new(new ClaimsIdentity(new[]{new Claim(identity.ClaimsIdentity.UserIdClaimType,"actor"),new Claim(identity.ClaimsIdentity.SecurityStampClaimType,stamp),new Claim(ClaimTypes.Role,"ServiceAdmin")}.Concat(session==null?[]:[new Claim(AuthenticationSession.SessionClaim,session)]).Concat(duplicate?[new Claim(identity.ClaimsIdentity.UserIdClaimType,"actor")]:[]),"synthetic"));
 Task<EventOverviewResult> Read(string id="e",ClaimsPrincipal? who=null)=>EventOverviewReader.ReadAsync(db,who??Who(),identity,id,DateTimeOffset.UtcNow);
 var e=new Sem.Web.Core.SessionEvent{Id="e",Title="合成 <img src=x>",Location="合成スタジオ",ScheduledDate="2030-11-14T13:00:00+09:00",OpensAt="2030-11-14T03:00:00Z",Description="<p>合成</p><script>PRIVATE_ACTIVE</script>",DescriptionFormat="html",ManualPhaseOverride=true,Phases=[new(){Id="hidden",EventId="e",Kind="Hidden",Name="非表示",IsActive=true},new(){Id="view",EventId="e",Kind="View",Name="閲覧"}]};db.SessionEvents.Add(e);await db.SaveChangesAsync();
 Check((await Read()).State=="not-found","役割claimだけで原文へアクセスできない");Check((await Read("missing")).State=="not-found","不明対象は同じ拒否");
 e.Admins.Add(new(){EventId="e",UserId="actor"});await db.SaveChangesAsync();var before=File.ReadAllBytes(file);var wal=File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[];var v=(await Read()).View!;
 Check(v.ActorId=="actor"&&v.EventId=="e"&&v.Description==e.Description&&v.DescriptionFormat=="html","現担当管理者へ原文と形式をそのまま渡す");Check(!v.DescriptionHtml.Contains("PRIVATE_ACTIVE")&&!v.DescriptionHtml.Contains("<script"),"公開描画と同じ無害化済み保存概要");Check(v.ScheduledDate=="2030-11-14T04:00:00.0000000+00:00"&&v.OpensAt=="2030-11-14T03:00:00.0000000+00:00","明示UTCへ正規化");Check(v.Color==null&&v.Mode==null&&v.Choices.Length==10,"独立した継承と保存済み候補");
 foreach(var secret in new[]{"PRIVATE_EMAIL","SecurityStamp","TokenHash","RowVersion","@example.invalid"})Check(!JsonSerializer.Serialize(v).Contains(secret),"秘密値なし "+secret);
 Check(before.SequenceEqual(File.ReadAllBytes(file))&&wal.SequenceEqual(File.Exists(file+"-wal")?File.ReadAllBytes(file+"-wal"):[])&&!db.ChangeTracker.HasChanges(),"DB・WAL・監査を変更しない");
 e.Admins.Clear();await db.SaveChangesAsync();Check((await Read()).State=="not-found","担当剥奪即反映");actor.IsAdmin=true;await db.SaveChangesAsync();Check((await Read()).State=="ok","現全体管理者は担当なしでも読取可");
 db.EventThemePreferences.Add(new(){EventId="e",ThemeId="rose",Mode=2});await db.SaveChangesAsync();v=(await Read()).View!;Check(v.Color=="rose"&&v.Mode=="dark","イベント層を個人層で上書きしない");var theme=await db.EventThemePreferences.SingleAsync();theme.Mode=9;try{await db.SaveChangesAsync();Check(false,"不正modeのDB拒否");}catch(DbUpdateException){Check(true,"不正modeはDB制約で拒否");}theme.Mode=2;theme.ThemeId="missing";try{await db.SaveChangesAsync();Check(false,"欠損候補のDB拒否");}catch(DbUpdateException){Check(true,"欠損候補は外部キーで拒否");}theme.ThemeId="rose";e.DescriptionFormat="unknown";await db.SaveChangesAsync();Check((await Read()).State=="invalid","未知形式をtextへ書き換えない");e.DescriptionFormat="html";e.OpensAt="2031-01-01T00:00:00Z";await db.SaveChangesAsync();Check((await Read()).State=="invalid","開場が開始後の不整合を拒否");e.OpensAt=null;await db.SaveChangesAsync();
 Check((await Read(who:new(new ClaimsIdentity()))).State=="unauthorized","匿名拒否");Check((await Read(who:Who("old"))).State=="unauthorized","古いstamp拒否");Check((await Read(who:Who(duplicate:true))).State=="unauthorized","多重claim拒否");Check((await Read(who:Who(session:null))).State=="unauthorized","sessionなし拒否");actor.Enabled=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","無効本人拒否");actor.Enabled=true;actor.EmailConfirmed=false;await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","未確認本人拒否");actor.EmailConfirmed=true;await db.SaveChangesAsync();db.RevokedAuthSessions.Add(new(){UserId=actor.Id,TokenHash=AuthenticationSession.Hash("session"),RevokedAt=DateTimeOffset.UtcNow.ToString("O")});await db.SaveChangesAsync();Check((await Read()).State=="unauthorized","失効sessionから原文なし");Console.WriteLine($"概要原文の現管理権限・無害化・参照不変 {checks}検査: 成功（合成DBのみ）");
}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();foreach(var p in new[]{file,file+"-wal",file+"-shm"})File.Delete(p);}
